<?php else: ?><section class="staff-panel catalog-panel"><h2><?= html_escape($business['name']) ?></h2><p>Kegiatan #<?= (int)$business['id'] ?> · Pelaku: <?= html_escape($business['owner_name']?:'Belum tercatat') ?> · <a href="<?= site_url('pengelola/registri/'.$business['id']) ?>">Lihat profil kegiatan</a></p>
<?php if(!$business['person_id']): ?><div class="alert alert-warning">Kegiatan ini belum terhubung ke pelaku utama. <a href="<?= site_url('pengelola/registri/'.$business['id']).'?tab=pelaku' ?>">Lengkapi pelaku pada profil kegiatan</a> sebelum membuat toko.</div><?php else: ?><form method="post" action="<?= site_url('pengelola/toko/baru').'?business_id='.(int)$business['id'].($person?'&person_id='.(int)$person_id:'') ?>"><input type="hidden" name="<?= $this->security->get_csrf_token_name() ?>" value="<?= $this->security->get_csrf_hash() ?>"><input type="hidden" name="business_id" value="<?= (int)$business['id'] ?>">
