<label>Kategori awal<select class="form-select" name="category_id" required><option value="">Pilih kategori</option><?php foreach($categories as $category): ?><option value="<?= (int)$category['id'] ?>" <?= (int)$this->input->post('category_id',TRUE)===(int)$category['id']?'selected':'' ?>><?= html_escape(($category['parent_name']?$category['parent_name'].' — ':'').$category['name']) ?></option><?php endforeach; ?></select></label>
