<label>Nama kontak<input class="form-control" name="contact_label" maxlength="120" value="<?= html_escape((string)$this->input->post('contact_label',TRUE)) ?>"></label>
<label>Deskripsi toko<textarea class="form-control" name="description" maxlength="5000" rows="4"><?= html_escape((string)$this->input->post('description',TRUE)) ?></textarea></label>
<button class="btn btn-primary" type="submit">Simpan toko sebagai draf</button></form><?php endif; ?></section><?php endif; ?>
